    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1);
        // Use a contract that reverts on any call (e.g., the test contract itself without fallback)
        address caddress = address(this);
        address[] memory tos = new address[](1);
        tos[0] = address(0x2);
        uint v = 100;
        bool ok;
        try c.transfer(from, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false); // reference reverts (ok=false), buggy version returns true (ok=true)
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that always reverts on transferFrom
        address token = address(new RevertingToken());
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint256 v = 1;

        bool ok;
        try c.transfer(from, token, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference contract reverts, buggy contract does not.
        // In a correct implementation, the transfer should revert.
        assertTrue(!ok, "The call should revert due to require(_s) enforcing success");
    }
}

contract RevertingToken {
    fallback() external payable {
        revert("always revert");
    }
}
